def reorder_by_priority_list_unlisted_first(items, priority):
    pos = {v: i for i, v in enumerate(priority)}
    unlisted = [x for x in items if x not in pos]
    listed = [x for x in items if x in pos]
    listed.sort(key=lambda x: pos[x])
    return unlisted + listed

def count_unordered_pairs(pairs):
    counts = {}
    for a, b in pairs:
        key = (a, b) if a <= b else (b, a)
        counts[key] = counts.get(key, 0) + 1
    return counts

