def median_index(nums):
    s = sorted(nums)
    n = len(s)
    if n % 2 == 1:
        val = s[n // 2]
    else:
        val = s[n // 2 - 1]
    return nums.index(val)

def wrap_text(text, width):
    words = text.split()
    lines = []
    current = ''
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= width:
            current += ' ' + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    return lines

def sentence_case_keep_i(s):
