def group_consecutive(lst):
    if not lst:
        return []
    result = []
    prev = lst[0]
    count = 1
    for x in lst[1:]:
        if x == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = x
            count = 1
    result.append([prev, count])
    return result

