def least_frequent_char(s):
    if not s:
        return ""
    freq = {}
    order = []
    for ch in s:
        if ch not in freq:
            freq[ch] = 0
            order.append(ch)
        freq[ch] += 1
    best = order[0]
    for ch in order[1:]:
        if freq[ch] < freq[best]:
            best = ch
    return best

def is_valid_weighted_checksum_alternating_sign(s):
    if len(s) < 2:
        return False
    body, check_c = s[:-1], s[-1]
    if not body.isdigit() or not check_c.isdigit():
        return False
    total = sum((1 if i % 2 == 0 else -1) * int(d) for i, d in enumerate(body))
    return int(check_c) == total % 10

def average_by_key_from_pairs(pairs):
    sums = {}
    counts = {}
    for k, v in pairs:
        sums[k] = sums.get(k, 0) + v
        counts[k] = counts.get(k, 0) + 1
    return {k: round(sums[k] / counts[k], 2) for k in sums}

