def is_power_of_k(n, k):
    if n < 1 or k < 2:
        return False
    while n % k == 0:
        n //= k
    return n == 1

def longest_increasing_run(lst):
    if not lst:
        return 0
    best = cur = 1
    for i in range(1, len(lst)):
        if lst[i] > lst[i-1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def count_happy_numbers_in_range(a, b):
    def is_happy(n):
        seen = set()
        while n != 1 and n not in seen:
            seen.add(n)
            n = sum(int(d) ** 2 for d in str(n))
        return n == 1
    return sum(1 for x in range(a, b + 1) if is_happy(x))

