def min_case_changes_alternating(s):
    letters = [ch for ch in s if ch.isalpha()]
    if not letters:
        return 0
    cost_upper_start = 0
    cost_lower_start = 0
    for i, ch in enumerate(letters):
        want_upper = (i % 2 == 0)
        is_upper = ch.isupper()
        if want_upper != is_upper:
            cost_upper_start += 1
        else:
            cost_lower_start += 1
    return min(cost_upper_start, cost_lower_start)

