def reindent(text, old_n, new_n):
    out = []
    prefix = " " * old_n
    for line in text.split("\n"):
        if line.startswith(prefix):
            out.append(" " * new_n + line[old_n:])
        else:
            out.append(line)
    return "\n".join(out)

def sliding_window_sums(lst, k):
